from pathlib import Path
from datetime import datetime,timezone
import json,hashlib,subprocess,sys,shutil
# Usage from repository root: python3 .riela/workflows/sqlserver-count-review/scripts/review.py engineer|validation
root=Path.cwd();role=sys.argv[1];assert role in ['engineer','validation']
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
proof=root/'results/sqlserver/owner-proof.json';guide=root/'docs/sqlserver-table-count-guideline.md';assert proof.is_file() and guide.is_file()
assert json.loads(proof.read_text())['status']=='owner_verified_container_benchmark'
if role=='validation':
 assert (root/'results/sqlserver/reviews/final-engineer-result.json').is_file()
name='temp-sqlserver-count-'+role+'-sol';base=root/'.private.handover/sqlserver-temp-workflows';dest=base/name;(dest/'nodes').mkdir(parents=True,exist_ok=True)
prompt='''You are a separate new GPT-6.1 Sol adversarial reviewer of the SQL Server whole-table count guideline. READ ONLY: no writing, DB/Docker connections, measurements, delegation, workflows, commit or push. Read AGENTS.md SQL Server override and results/sqlserver/reviews/acceptance-criteria.json. Review docs/sqlserver-table-count-guideline.md and its links, sqlserver source and actual raw results, results/sqlserver/owner-proof.json. Verify all claimed hashes, actual status/exit/source/integrity/cleanup evidence and the support boundary ARM64/amd64 emulation. Owner summaries and author claims are not independent proof.
Act as ROLE. Your priority is whether an unfamiliar engineer can obtain whole-table counts for huge service DBs without degradation, with explicit safe deferral where prerequisites cannot be met. Do not substitute engine encyclopedia or exhaustive grids. Challenge metadata visibility/partition/index doublecount, approximate vs exact vs stats-at-update, RLS count scope, bigint overflow, zero/NULL/permissions/errors not empty, ROWVERSION read assumptions vs default locking RC, Sch-S/DDL, tempdb/PVS/version retention, backup provisioning/resource isolation/shared readable secondaries/redo/freshness, commandtimeout vs locktimeout, query/session ownership/currentSPID/cancellation/serverend/recovery, live workload conservation/unfinished/censored/sparse windows, cache/index/order/TDE state, client key vs server keys and unmeasured AlwaysEncrypted. Check claimed max/min error and conditions by recomputing cited raw JSON; do not accept universal few%/10% guarantees or N-only safe primary scan thresholds. No oldMySQL nonlocking assumptions imported. NOLOCK/READPAST/whole-table-lock or deliberate contention injection not allowed. Do not request excluded dangerous experiments. Counts must be RCSI or SNAPSHOT qualified; no automatic production isolationconfiguration change. Existing inventory/approvedexport first, no primaryextraSQL withoutbudget, resourcecaps before monitoring, no viablepath=>defer. Compare simpler/faster viable alternatives forrequiredprecision andfreshness, no unsupported globalranking. 100M/80/100col/encryption actual measurement vs missing combinations must be distinguishable, nativeproductionperformance not inferred fromemulation.
Raise only actual operational material defects with concrete scenario/source/evidence/correction, not stylistic preferences. High/middle and necessary measurement gaps block acceptance. Do not demand every possible experiment if safe explicitly limited guidance resolves the decision. Accept only exact current guide and linked details/proof/source verified, no blocking defect/necessary experiment pending. Preserve failures/unknowns, never mark skipped coveragepassed. Return SMALL JSON: accepted boolean, decision accepted/rejected, role, guidelineSha256, proofSha256, findings array(id,severity,scenario,evidence,requiredCorrection), requestedExperiments array(onlyindispensable,whydecisiondepends), reviewQuestions object(betterMethods,designCoverage,omissions,lockFactors,fastCount), reviewEvidence array concrete files/fields/hash/recomputation. Do not assert otherrole acceptance without artifact.
'''.replace('ROLE','unfamiliar service engineer following the guide' if role=='engineer' else 'adversarial validation/operations reviewer, first independently reviewing current guide/evidence BEFORE opening the first review results/sqlserver/reviews/final-engineer-result.json; then assess each first-review finding using evidence and include independentFindingAssessment array')
prompt+='\nRead results/sqlserver/reviews/owner-open-findings.json and independently verify the actual corrections to every owner material finding; disposition labels alone are not proof.\n'
prompt+='\nExact inputs: '+json.dumps({'guideSha256':sha(guide),'proofSha256':sha(proof)})
node={'id':'review','executionBackend':'codex-agent','model':'gpt-6.1-sol','modelFreeze':True,'effort':'high','agentSandbox':'read-only','sessionPolicy':{'mode':'new'},'variables':{},'promptTemplate':prompt,'output':{'jsonSchema':{'type':'object','required':['accepted','decision','guidelineSha256','proofSha256','findings','requestedExperiments','reviewQuestions','reviewEvidence'],'properties':{'accepted':{'type':'boolean'},'decision':{'enum':['accepted','rejected']},'guidelineSha256':{'type':'string'},'proofSha256':{'type':'string'},'findings':{'type':'array'},'requestedExperiments':{'type':'array'},'reviewQuestions':{'type':'object'},'reviewEvidence':{'type':'array'}},'additionalProperties':True},'maxValidationAttempts':2}}
wf={'workflowId':name,'description':'Separate Sol adversarial SQL Server count review '+role,'defaults':{'nodeTimeoutMs':3600000,'maxLoopIterations':1},'entryStepId':'review','nodes':[{'id':'review','nodeFile':'nodes/review.json'}],'steps':[{'id':'review','nodeId':'review','role':'worker'}]}
(dest/'workflow.json').write_text(json.dumps(wf,indent=2)+'\n');(dest/'nodes/review.json').write_text(json.dumps(node,ensure_ascii=False,indent=2)+'\n')
out=root/'results/sqlserver/reviews';stamp=datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ');attempt=out/(role+'-'+stamp);attempt.mkdir()
for p in [guide,proof,root/'sqlserver/README.md',dest/'workflow.json',dest/'nodes/review.json']:shutil.copyfile(p,attempt/p.name)
launch={'startedAt':datetime.now(timezone.utc).isoformat(),'role':role,'model':'gpt-6.1-sol','guidelineSha256':sha(guide),'proofSha256':sha(proof),'attempt':str(attempt.relative_to(root))};(out/('final-'+role+'-launch.json')).write_text(json.dumps(launch,indent=2)+'\n')
with (attempt/'validation.json').open('w') as f:subprocess.run(['riela','workflow','validate',name,'--workflow-definition-dir',str(base),'--output','json'],check=True,stdout=f)
with (attempt/'run.log').open('w') as f:r=subprocess.run(['riela','workflow','run',name,'--workflow-definition-dir',str(base),'--working-dir',str(root),'--session-store',str(root/'.riela/sessions'),'--artifact-root',str(root/'.riela/artifacts'),'--max-steps','1','--output','jsonl'],stdout=f,stderr=subprocess.STDOUT)
launch.update(exitCode=r.returncode,finishedAt=datetime.now(timezone.utc).isoformat())
for line in (attempt/'run.log').read_text().splitlines():
 try:e=json.loads(line)
 except ValueError:continue
 if e.get('type')=='session_started':launch['sessionId']=e['sessionId'];break
if launch.get('sessionId'):
 runtime=json.loads((root/'.riela/artifacts'/launch['sessionId']/'runtime-snapshot.json').read_text());launch['runtimeStatus']=runtime['session']['status'];result=runtime.get('rootOutput')
 if result is not None:
  (out/('final-'+role+'-result.json')).write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n');(attempt/'result.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n')
(out/('final-'+role+'-launch.json')).write_text(json.dumps(launch,indent=2)+'\n');(attempt/'launch.json').write_text(json.dumps(launch,indent=2)+'\n');(attempt/'manifest.json').write_text(json.dumps({'files':{str(p.relative_to(attempt)):sha(p) for p in attempt.rglob('*') if p.is_file()}},indent=2)+'\n');print(json.dumps(launch))
